{
  "title": "The Mirror Crossing",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "Mara studies the ruined city from a hill.",
      "visual_description": "Mara stands on a grassy hill overlooking the shattered skyline of the royal city, broken towers and torn banners visible in the distance.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 2,
      "caption": "Glass Diver steps out of a shattered window.",
      "visual_description": "Glass Diver emerges from a cracked mirror propped against a wall, his helmet gleaming as he adjusts his coat.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 3,
      "caption": "Oracle Lamp flickers a warning about the castle gates.",
      "visual_description": "On a stone table, Oracle Lamp sputters, its single eye darting as it casts shadows of iron gates onto the wall.",
      "characters": ["oracle_lamp"]
    },
    {
      "scene_number": 4,
      "caption": "Tin Fox scampers ahead to scout the first barrier.",
      "visual_description": "Tin Fox noses through rubble, its key-wind tail ticking, blue eyes scanning a collapsed archway.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 5,
      "caption": "Sleeping Tax Collector snores in a half-ruined booth.",
      "visual_description": "In a toppled toll booth, Sleeping Tax Collector uses a ledger as a pillow, stamp paper stuck to his sleeve.",
      "characters": ["sleeping_tax_collector"]
    },
    {
      "scene_number": 6,
      "caption": "Mara marks a path past the cursed tower.",
      "visual_description": "Mara sketches a route on her map while glancing at a spiraling tower wrapped in thorny vines, brass compass in hand.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 7,
      "caption": "Glass Diver peers into a dark well for an escape route.",
      "visual_description": "Glass Diver kneels by a stone well, his diving helmet reflecting the moon as he looks into the dark water.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 8,
      "caption": "Oracle Lamp warns of a patrol of armored figures.",
      "visual_description": "Oracle Lamp's flame shrinks as it whispers, its eye fixed on a distant line of armored figures marching among ruins.",
      "characters": ["oracle_lamp"]
    },
    {
      "scene_number": 9,
      "caption": "Tin Fox triggers a hidden mechanism near the gates.",
      "visual_description": "Tin Fox presses a loose stone with its paw, causing a grinding sound from the castle gates ahead.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 10,
      "caption": "Sleeping Tax Collector stirs but doesn't wake.",
      "visual_description": "Sleeping Tax Collector murmurs in his sleep, rolling over and sending stamped papers fluttering into the air.",
      "characters": ["sleeping_tax_collector"]
    },
    {
      "scene_number": 11,
      "caption": "Mara leads the group through a magic door.",
      "visual_description": "Mara pushes open a shimmering stone door, its surface rippling like water, as she steps through with compass raised.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 12,
      "caption": "Glass Diver swims through a mirror into a locked chamber.",
      "visual_description": "Glass Diver presses his hand against a tall mirror, then passes through it like liquid, entering a dusty room.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 13,
      "caption": "Oracle Lamp reveals a rumor of a dragon is false.",
      "visual_description": "Oracle Lamp's eye narrows as it shows a vision of a broken clockwork construct, not a dragon, on the tower.",
      "characters": ["oracle_lamp"]
    },
    {
      "scene_number": 14,
      "caption": "Tin Fox finds a hidden passage under old royal banners.",
      "visual_description": "Tin Fox sniffs beneath tattered red and gold banners hanging from a collapsed wall, revealing a dark tunnel.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 15,
      "caption": "Sleeping Tax Collector is carried through the passage.",
      "visual_description": "Glass Diver and Mara lift the dozing tax collector, his ledger still tucked under his arm, as they enter the tunnel.",
      "characters": ["sleeping_tax_collector", "glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 16,
      "caption": "Mara consults her map at a crossroads.",
      "visual_description": "Mara unrolls her ink-stained map under a flickering lamp, tracing a line to the bridge exit.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 17,
      "caption": "The group races across the final bridge.",
      "visual_description": "Glass Diver, Mara, Tin Fox, Oracle Lamp, and the still-sleeping tax collector sprint across a stone bridge as it begins to crumble.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox", "oracle_lamp", "sleeping_tax_collector"]
    },
    {
      "scene_number": 18,
      "caption": "They escape into the wilderness beyond the city.",
      "visual_description": "The group stands on a hillside, looking back at the ruined city as dawn breaks, Oracle Lamp's flame steady.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox", "oracle_lamp", "sleeping_tax_collector"]
    }
  ]
}

